// Minimal re-implementation of Python's argparse behavior for this script.
// Supports: required string options (--name value / --name=value),
// -h/--help, usage/error formatting, and argparse exit codes.

import { basename } from 'node:path';

export class ArgumentParser {
  constructor({ prog } = {}) {
    // Python argparse defaults prog to os.path.basename(sys.argv[0]).
    this.prog = prog ?? basename(process.argv[1] ?? 'test4.mjs');
    this.arguments = [{ names: ['-h', '--help'], help: 'show this help message and exit', isHelp: true }];
  }

  addArgument(name, { required = false } = {}) {
    this.arguments.push({
      names: [name],
      metavar: name.replace(/^--/, '').toUpperCase(),
      required,
      isHelp: false,
    });
  }

  formatUsage() {
    const parts = ['[-h]'];
    for (const arg of this.arguments) {
      if (arg.isHelp) continue;
      parts.push(`${arg.names[0]} ${arg.metavar}`);
    }
    return `usage: ${this.prog} ${parts.join(' ')}`;
  }

  formatHelp() {
    const lines = [this.formatUsage(), '', 'options:'];
    lines.push('  -h, --help  show this help message and exit');
    for (const arg of this.arguments) {
      if (arg.isHelp) continue;
      lines.push(`  ${arg.names[0]} ${arg.metavar}`);
    }
    return lines.join('\n');
  }

  error(message) {
    process.stderr.write(this.formatUsage() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  parseArgs(argv = process.argv.slice(2)) {
    const result = {};
    const extras = [];
    const seen = new Set();
    const byName = new Map();
    for (const arg of this.arguments) {
      for (const n of arg.names) byName.set(n, arg);
    }

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];
      let name = token;
      let inlineValue = null;
      if (token.startsWith('--') && token.includes('=')) {
        const idx = token.indexOf('=');
        name = token.slice(0, idx);
        inlineValue = token.slice(idx + 1);
      }

      const arg = byName.get(name);
      if (!arg) {
        extras.push(token);
        continue;
      }

      if (arg.isHelp) {
        process.stdout.write(this.formatHelp() + '\n');
        process.exit(0);
      }

      let value;
      if (inlineValue !== null) {
        value = inlineValue;
      } else {
        if (i + 1 >= argv.length || byName.has(argv[i + 1])) {
          this.error(`argument ${arg.names[0]}: expected one argument`);
        }
        value = argv[++i];
      }
      result[arg.names[0].replace(/^--/, '')] = value;
      seen.add(arg.names[0]);
    }

    const missing = this.arguments
      .filter((a) => !a.isHelp && a.required && !seen.has(a.names[0]))
      .map((a) => a.names[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return result;
  }
}

