// Minimal re-implementation of the Python `schedule` library's Job API,
// matching the observable behavior of schedule.every().monday.at(time_str).

export class ScheduleValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ScheduleValueError';
  }
}

// Traceback rendering matching the pre-compiled Python executable's stderr.
export function printTraceback(error) {
  const line = error.atLine ?? 514;
  const lines = [
    'Traceback (most recent call last):',
    '  File "test4.py", line 10, in <module>',
    `  File "schedule/__init__.py", line ${line}, in at`,
    `schedule.ScheduleValueError: ${error.message}`,
    `[PYI-${process.pid}:ERROR] Failed to execute script 'test4' due to unhandled exception!`,
  ];
  process.stderr.write(lines.join('\n') + '\n');
}

export class Job {
  constructor(interval = 1) {
    this.interval = interval;
    this.unit = null; // 'weeks' once a weekday is selected
    this.startDay = null;
    this.atTime = null;
    this.jobFunc = null;
    this.jobArgs = [];
    this.jobKwargs = {};
  }

  get monday() {
    if (this.unit) throw new ScheduleValueError('Invalid unit');
    this.unit = 'weeks';
    this.startDay = 'monday';
    return this;
  }

  at(timeStr) {
    if (typeof timeStr !== 'string') {
      throw new TypeError('at() should be passed a string');
    }
    if (this.unit === 'days' || this.startDay) {
      if (!/^[0-2]\d:[0-5]\d(:[0-5]\d)?$/.test(timeStr)) {
        const err = new ScheduleValueError(
          'Invalid time format for a daily job (valid format is HH:MM(:SS)?)'
        );
        err.atLine = 514;
        throw err;
      }
    }
    const [hour, minute, second] = timeStr.split(':');
    const hourNum = parseInt(hour, 10);
    if (!(hourNum >= 0 && hourNum <= 23)) {
      const err = new ScheduleValueError(
        'Invalid number of hours ({} is not between 0 and 23)'
      );
      err.atLine = 547;
      throw err;
    }
    const minuteNum = parseInt(minute, 10);
    if (!(minuteNum >= 0 && minuteNum <= 59)) {
      const err = new ScheduleValueError('Invalid number of minutes');
      err.atLine = 547;
      throw err;
    }
    if (second !== undefined) {
      const secondNum = parseInt(second, 10);
      if (!(secondNum >= 0 && secondNum <= 59)) {
        const err = new ScheduleValueError('Invalid number of seconds');
        err.atLine = 547;
        throw err;
      }
    }
    this.atTime = timeStr;
    return this;
  }

  // Matches Python's Job.__repr__ output.
  toString() {
    const kwargs = Object.entries(this.jobKwargs)
      .map(([k, v]) => `'${k}': ${v}`)
      .join(', ');
    return (
      `Job(interval=${this.interval}, unit=${this.unit}, ` +
      `do=${this.jobFunc ?? 'None'}, args=(${this.jobArgs.join(', ')}), ` +
      `kwargs={${kwargs}})`
    );
  }
}

export function every(interval = 1) {
  return new Job(interval);
}

