// Python original:
//   parser.add_argument('--a', type=str, required=True)
//   parser.add_argument('--b', type=str, required=True)
//   parser.add_argument('--c', type=str, required=True)
//   job = schedule.every().monday.at(args.a)
//   print(job)

import { ArgumentParser } from './lib/argparse.mjs';
import { every, ScheduleValueError, printTraceback } from './lib/schedule.mjs';

const parser = new ArgumentParser();
parser.addArgument('--a', { required: true });
parser.addArgument('--b', { required: true });
parser.addArgument('--c', { required: true });
const args = parser.parseArgs();

try {
  const job = every().monday.at(args.a); // 创建每周一特定时间作业
  console.log(String(job));
} catch (err) {
  if (err instanceof ScheduleValueError) {
    printTraceback(err);
    process.exit(1);
  }
  throw err;
}

